634	// copy samples from 16bit into 32bit with applying window function
635	inline static void
636	window_complex_15to31(q15_t *s1, q15_t *s2, size_t length)
637	{
638	    q31_t *dest = spdisp_fetch_current;
639	    const q15_t *wf = spdisp_wf_current;
640	    spdisp_fetch_current += length * 2;
641		spdisp_fetch_rest -= length * 2;
642	    spdisp_wf_current += length;
643	
644		length /= 2;
645		while (length-- > 0) {
646			uint32_t w = *__SIMD32(wf)++;
647			uint32_t i1i2 = *__SIMD32(s1)++;
648			uint32_t q1q2 = *__SIMD32(s2)++;
649			*dest++ = __SMULBB(i1i2, w) << mag_shift;
650			*dest++ = __SMULBB(q1q2, w) << mag_shift;
651			*dest++ = __SMULTT(i1i2, w) << mag_shift;
652			*dest++ = __SMULTT(q1q2, w) << mag_shift;
653		}
654	}
