665		length /= 2;
666		while (length-- > 0) {
667			uint32_t w = *__SIMD32(wf)++;
668			uint32_t i1i2 = *__SIMD32(s1)++;
669			*dest++ = __SMULBB(i1i2, w) << mag_shift;
670			*dest++ = 0;
671			*dest++ = __SMULTT(i1i2, w) << mag_shift;
672			*dest++ = 0;
673		}
674	}
