676	// copy samples from 16bit into 32bit with applying window function
677	inline static void
678	window_complex_interleaved_15to31(q15_t *src, size_t length)
679	{
680	    q31_t *dest = spdisp_fetch_current;
681	    const q15_t *wf = spdisp_wf_current;
682	    spdisp_fetch_current += length;
683		spdisp_fetch_rest -= length;
684	    spdisp_wf_current += length / 2;
685	
686		length /= 4;
687		while (length-- > 0) {
688			uint32_t w = *__SIMD32(wf)++;
689			uint32_t i1q1 = *__SIMD32(src)++;
690			uint32_t i2q2 = *__SIMD32(src)++;
