48	                     uint8_t     mult,
49	                     uint32_t    num,
50	                     uint32_t    denom)
51	{
52	  /* Get the appropriate starting point for the PLL registers */
53	  const uint8_t pllreg_base[] = {
54	    SI5351_REG_26_PLL_A,
55	    SI5351_REG_34_PLL_B
56	  };
57	  uint32_t P1;
58	  uint32_t P2;
59	  uint32_t P3;
