75	    P1 = 128 * mult - 512;
76	    P2 = 0;
77	    P3 = 1;
78	  }
79	  else
80	  {
81	    /* Fractional mode */
82	    //P1 = (uint32_t)(128 * mult + floor(128 * ((float)num/(float)denom)) - 512);
83	    P1 = 128 * mult + ((128 * num) / denom) - 512;
84	    //P2 = (uint32_t)(128 * num - denom * floor(128 * ((float)num/(float)denom)));
85	    P2 = 128 * num - denom * ((128 * num) / denom);
86	    P3 = denom;
87	  }
